import faulthandler, hashlib, json, os, sys, glob
faulthandler.dump_traceback_later(60, exit=True)
sys.stdin = open(os.devnull)
def h(p):
    return hashlib.sha256(open(p, "rb").read()).hexdigest()
changed = ["benchmark/scripts/score.py", "benchmark/results/challenges.json",
           "benchmark/challenges/library-icon-tests.json", "benchmark/challenges/library-specialty.json",
           "benchmark/challenges/scorer-fix-0165.md"]
prep = json.load(open("benchmark/preparation.json"))
old = {}
for items in prep["milestones"].values():
    for e in items:
        if e["path"] in changed:
            old[e["path"]] = e["sha256"]
print("old pins", old)
p = os.path.abspath("benchmark/scripts/score.py")
g = {"__file__": p, "__name__": "score_run"}
exec(compile(open(p, "rb").read(), p, "exec"), g)
sys.argv = ["score.py"]
print("main rc", g["main"]())
d = json.load(open("benchmark/results/challenges.json"))
print("quality_measured", d["quality_measured"], d["totals"])
new = {c: h(c) for c in changed}
print("new", new)
files = glob.glob("benchmark/**/*.json", recursive=True)
for f in files:
    t = open(f, encoding="utf-8").read()
    n = t
    for path, oh in old.items():
        if oh != new[path]:
            n = n.replace(oh, new[path])
    if n != t:
        open(f, "w", encoding="utf-8").write(n)
        print("repinned", f)
for f in files:
    t = open(f, encoding="utf-8").read()
    for path, oh in old.items():
        if oh != new[path] and oh in t:
            print("STALE", f, path)

